const raw = $input.first().json.message;
const data = typeof raw === 'string' ? JSON.parse(raw) : raw;

// 1. 取得感測器名稱
const sensorId = data.sensor_id || data.sensor_name || data.sensor;

// 2. 依序尋找可能的數值或狀態欄位
let rawVal = data.value ?? data.temperature ?? data.weight ?? data.voltage 
          ?? data.vibration ?? data.co ?? data.h2 ?? data.hf 
          ?? data.smoke ?? data.magnetic ?? data.status ?? data.result 
          ?? data.condition ?? data.classification ?? data.class;

// 若以上都沒對到，自動抓 JSON 裡第一個不是 sensor_id / seq / timestamp 的欄位
if (rawVal === undefined) {
  const ignoreKeys = new Set(['sensor_id', 'sensor_name', 'sensor', 'seq', 'sequence_number', 'timestamp', 'time', 'ip', 'mac']);
  const valKey = Object.keys(data).find(k => !ignoreKeys.has(k));
  if (valKey) rawVal = data[valKey];
}

// 3. 轉成數字（避免文字變成 NaN -> null）
let numVal = Number(rawVal);
if (Number.isNaN(numVal)) {
  const str = String(rawVal).toLowerCase();
  if (['ok', 'normal', 'pass', 'true', 'yes', 'li-ion'].includes(str)) {
    numVal = 1;
  } else if (['damaged', 'error', 'rejected', 'fail', 'false', 'no'].includes(str)) {
    numVal = 0;
  } else {
    numVal = -1; // 其他未知文字分類的預設代碼
  }
}

return [{
  json: {
    sensor_id: sensorId,
    seq: Number(data.seq ?? data.sequence_number ?? 0),
    value: numVal,
    battery_type: data.battery_type ?? null,
    confidence_score: data.confidence_score !== undefined ? Number(data.confidence_score) : null,
    raw_condition: data.condition ?? null
  }
}];
